insert into public.questions (question_id,paper_id,question_number,question_type,question_text,option_a,option_b,option_c,option_d,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('110-2301-001','110-2301',1,'single_choice','關於我國憲政體制下之民主，下列敘述何者錯誤？','以代議民主為主，直接民主為輔','總統、副總統及立法委員由人民直接選舉產生','行政院對立法院負責，係直接民主制度之體現','人民對重大政策以投票方式直接決定，與代議民主相輔相成','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-2301-002','110-2301',2,'single_choice','依司法院大法官解釋意旨，關於外國人之暫時收容，下列敘述何者錯誤？','對外國人之暫時收容處分，須由法院事前為之','憲法第8 條所稱法定程序，及於暫時收容之非刑事程序','外國人之人身自由亦受憲法之保障','主管機關依法於合理作業期間內暫時收容外國人，非憲法所不許','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-2301-003','110-2301',3,'single_choice','依司法院大法官解釋意旨，有關軍事審判，下列敘述何者正確？','依憲法規定，軍事審判機關對軍人犯罪有專屬審判權','軍事審判之建制及訴訟程序，憲法已設有明文規定','軍事審判機關所行使者，雖屬國家刑罰權，但不具司法權之性質','本於憲法之意旨，應就軍事審判制度依平時與戰時分別規範','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-2301-004','110-2301',4,'single_choice','依司法院大法官解釋意旨，下列何法律規定涉及憲法第10 條遷徙自由之限制？','汽車駕駛人拒絕接受酒精濃度測試之檢定者，得吊銷其駕駛執照','無正當理由，跟追他人，經勸阻不聽者，得處罰鍰或申誡','被繼承人在臺灣地區之遺產，由出生於大陸地區人民依法繼承者，其所得財產總額，每人不得逾新 臺幣200 萬元','臺灣地區無戶籍國民入國應申請許可','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-2301-005','110-2301',5,'single_choice','依司法院大法官解釋意旨，有關憲法保障之言論及出版自由，下列敘述何者錯誤？','性言論之表現與性資訊之流通，不問是否出於營利之目的，均受憲法言論及出版自由之保障','為維持性道德感情與社會風化，釋憲者就立法者關於社會多數共通價值所為之判斷，原則上應予尊重','刑法第235 條所稱猥褻之資訊、物品，因「猥褻」屬不確定法律概念，違反法律明確性原則','憲法對言論及出版自由之保障尚非絕對，法律非不得依其性質而為必要之限制','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-2301-006','110-2301',6,'single_choice','依司法院大法官解釋意旨，關於秘密通訊自由之限制，下列敘述何者錯誤？','秘密通訊自由乃憲法保障隱私權之具體態樣之一','其法律限制要件應具體、明確，不得逾越必要之範圍','警察機關偵查犯罪而需要監察人民秘密通訊時，原則上應聲請法院核發通訊監察書','通訊監察未限制人身自由，尚非刑事訴訟上之強制處分','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-2301-007','110-2301',7,'single_choice','依司法院大法官解釋意旨，有關結社自由，下列敘述何者錯誤？','結社自由與人民發展其個人人格相關','各種團體雖然性質有所不同，但其結社自由受法律保障之程度，不得有所差異','結社自由之保障包含團體之存續、內部組織與事務之自主決定及對外活動之自由','單純僅因人民團體主張共產主義或分裂國土，即於申請時不予許可，並不合憲','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('110-2301-008','110-2301',8,'single_choice','有關特別公課，依司法院大法官解釋意旨，下列敘述何者錯誤？','特別公課與稅捐之性質不同','特別公課之徵收係基於特定政策目的需要，無須適用法律保留原則','空氣污染防制費之性質為特別公課','工業區開發管理基金兼具特別公課與使用規費之性質','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-009','110-2301',9,'single_choice','依司法院大法官解釋意旨，有關隱私權之敘述，下列何者錯誤？','為保障個人日常私密領域免於他人侵擾，隱私權為絕對不可限制之基本權利','隱私權為憲法第22 條之人民其他自由權利','資訊隱私權保障人民自主決定是否揭露其個人資料','資訊隱私權保障人民對其個人資料之使用有知悉與控制權','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-010','110-2301',10,'single_choice','臺北市政府若依法律規定公告「臺北市政府員工性騷擾防治辦法」，此一辦法係在保障下列何種憲法 上權利？','地方自治權','契約自由','人格權','財產權','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-011','110-2301',11,'single_choice','關於總統行使憲法職權，下列敘述何者錯誤？','總統認為有必要時，得咨請立法院召開臨時會','於監察院副院長任期屆滿前，總統負有適時提名繼任人選咨請立法院同意之義務','總統非經罷免或解職，概不受刑事上之訴究','總統行使職權有違法情事者，得受立法院之彈劾','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-012','110-2301',12,'single_choice','依司法院大法官有關言論自由之解釋意旨，下列敘述何者正確？','商業言論之事前審查當然違憲','猥褻性言論不在言論自由的保障範圍內','法律規定，具醫療性之藥物，於刊播廣告前申請主管機關核准，尚屬合憲','言論自由之保護範疇及限制準則，不因言論之性質而有不同','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-013','110-2301',13,'single_choice','依憲法增修條文規定，關於立法委員之選舉，下列敘述何者錯誤？','立法委員總額為113 人','立法委員的選舉為「單一選區兩票制」','政黨得票比率在5%以上者，方得分配不分區代表的席次','全國不分區立法委員之人數，約占立法委員總額之一半','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-014','110-2301',14,'single_choice','依司法院大法官解釋意旨，關於立法院職權之行使，下列敘述何者錯誤？','立法院為有效行使憲法職權，享有案件調閱權，經院會決議得向檢察機關調閱偵查中案件相關卷證','行政院停止執行預算，若涉及國家重要事項，立法院得要求行政院提出報告並備質詢','立法院應適時行使監察委員提名名單之人事同意權，不得以消極不行使之方式，危害監察院之正常 運行','立法院於休會期間提出不信任案者，應即召開臨時會審議之','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-015','110-2301',15,'single_choice','監察委員提出糾正案之目的為何？','懲戒失職公務員','追究首長法律責任','督促司法機關依法審判','促請行政部門改善工作','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-016','110-2301',16,'single_choice','下列何者屬於立法院得行使彈劾權之對象？','內政部部長','大法官','總統','考試委員','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-017','110-2301',17,'single_choice','有關司法獨立之敘述，下列何者正確？','司法院之年度司法概算，由司法院直接提送立法院審議','大法官皆受終身職待遇之保障','法官非依法律不得減俸','司法院概不得就審理事項發布規則','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('110-2301-018','110-2301',18,'single_choice','各級法院法官於審理案件時，對於應適用之法律，認為有牴觸憲法之疑義者，如何處理？','自行審查，於認定法律為違憲後，於個案中拒絕適用之','自行裁定停止訴訟程序，聲請司法院解釋','自行審查，於認定法律為違憲後，宣告法律違憲並失效','須呈請所屬法院院長核可後，裁定停止訴訟程序，聲請司法院解釋','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-019','110-2301',19,'single_choice','關於憲法上土地政策，下列敘述何者正確？','土地增值稅已經憲法明定，法律得授權地方政府擬訂基本稅率','開徵地價稅之稅目屬地方自治權','公用徵收是專由中央立法並執行之事項','土地增值稅屬於國稅或地方稅，由行政院決定','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-020','110-2301',20,'single_choice','依司法院大法官解釋意旨，有關地方議會議員之言論免責權，下列敘述何者正確？','地方議會議員言論免責權，憲法無保障之明文規定','地方議會議員不同於國會議員，其言論不受免責權保障','為使地方議會議員順利執行職務，其於議會會議時之一切言論，均受免責權之保障','在民主時代，地方議會議員言論免責權保障不合時宜，應予以廢除','憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-021','110-2301',21,'single_choice','法官於審判案件時，對於下列何者可予以引用，但仍得依據法律，表示適當之不同見解？','身心障礙者權利公約中保障身心障礙者人權之規定','緊急命令','行政函釋','司法院大法官之憲法解釋','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-022','110-2301',22,'single_choice','依司法院大法官解釋意旨，有關公法上信賴保護原則之敘述，下列何者錯誤？','人民明知無自耕能力，仍提供不正確資料，申請發放自耕能力證明書，不生信賴保護之問題','法律有溯及適用之特別規定，且溯及適用之結果有利於人民者，無違信賴保護原則','行政法規發布施行後，訂定或發布法規之機關依法定程序予以修改，無須兼顧規範對象信賴利益之 保護','行政法規之修正，得以訂定過渡條款之方式，保護當事人之信賴','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-023','110-2301',23,'single_choice','下列何者為獨立機關？','行政院國家永續發展委員會','中央選舉委員會','中央廉政委員會','總統府人權諮詢委員會','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-024','110-2301',24,'single_choice','有關管轄權變動之敘述，下列何者正確？','行政程序法所規定之權限委任，亦包含下級機關將權限委由上級機關行使之情形','內政部將某項職掌委由直轄市行使，性質上為權限委託','就受託行使公權力而言，對外須以受託之私人團體或個人名義行文','就受託行使公權力而言，行政機關僅得以行政處分之方式將權限授予私人','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-025','110-2301',25,'single_choice','鄉公所因減編鄉民代表會預算，遭鄉民代表會大幅刪減總預算，鄉公所提請覆議遭維持原決議，報請 縣政府協商未達共識，縣政府逕為決定增列鄉民代表會預算。如該筆預算已執行完畢，而鄉公所對該 增列決定仍不服時，依司法實務見解，得為如何之法律救濟？','就該決定提起確認行政處分違法訴訟','提起一般給付訴訟，請求返還不當得利','逕向司法院聲請解釋','就該決定向內政部提起訴願','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-026','110-2301',26,'single_choice','依地方制度法規定及司法院大法官解釋意旨，針對下列何種爭議，得逕向司法院聲請解釋？','直轄市議會就直轄市政府對直轄市議會之議決案未提起覆議而延不執行之爭議','直轄市議會議員現有總額五分之一對於議會通過之決議案認為有牴觸憲法之疑義','行政院就直轄市議會所制定之自治條例予以函告無效，直轄市議會認為有違背憲法之疑義','直轄市政府就直轄市與縣（市）間之事權發生爭議，尚未請行政院解決者','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-027','110-2301',27,'single_choice','依司法院大法官解釋意旨，有關公務員免職構成要件之規定，下列敘述何者正確？','得由公務人員考績法施行細則定之','得由服務機關以職權命令定之','應由法律定之，方符合憲法意旨','得由各機關以獎懲基準定之','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('110-2301-028','110-2301',28,'single_choice','有關對公務人員甲作成一次記二大過專案考績免職處分，下列敘述何者正確？','免職處分作成前應通知甲陳述意見，使其對免職事由有答辯機會，免職處分應對甲為合法送達','經檢察官起訴之案件，因檢察官起訴書所載犯罪事實，均屬「客觀上明白足以確認之事實」，服務 機關一律無須通知當事人陳述意見','免職處分作成前無須通知甲陳述意見，於免職處分中載明免職事由及法令依據即為已足','免職處分作成前應通知甲陳述意見，但若免職處分送達時由甲親收，免職處分不因未給予甲陳述意 見而違法','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-2301-029','110-2301',29,'single_choice','下列何者不直接對外發生法規範效力？','行政訴訟法施行法','高雄市山地原住民區改制辦法','臺北市政府交通局利用道路舉辦臨時活動審議作業程序','違反道路交通管理事件統一裁罰基準及處理細則','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('110-2301-030','110-2301',30,'single_choice','關於行政命令之效力，下列敘述何者正確？','法規命令由訂定機關發布，並經立法院審查確認合法性後，始發生效力','行政規則自有效下達下級機關或屬官時起，發生效力','法規命令無法律之授權而剝奪或限制人民之自由或權利者，非當然無效','廢止解釋性規定之行政規則，只須經原機關為之，無須刊登政府公報','行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
